@@ -4792,0 +4792,18 @@
+// Fuse DecodeN and LoadN: when compressed oops are zero-based and unscaled,
+// decoding is a no-op zero-extension, which lwu already performs.
+instruct loadN2P_unscaled(iRegPNoSp dst, memory mem)
+%{
+    predicate(CompressedOops::shift() == 0 && n->in(1)->as_Load()->is_unordered() &&
+              n->in(1)->as_Load()->barrier_data() == 0);
+    match(Set dst (DecodeN (LoadN mem)));
+
+    ins_cost(LOAD_COST);
+    format %{ "lwu $dst, $mem\t# compressed ptr decode (zero-based unscaled)" %}
+
+    ins_encode %{
+       __ lwu(as_Register($dst$$reg), Address(as_Register($mem$$base), $mem$$disp));
+    %}
+
+    ins_pipe(iload_reg_mem);
+%}
+
